-- =============================================================================
-- Kotobaya V1 schema (Flyway). Contract file: see contracts/db/SCHEMA.md.
--
--   ref.*  reference data  - read-only for clients, replaced by dict-refresh.
--   app.*  learning data, media, and system tables.
--
-- Conventions (binding for every implementer):
--   * All ids are UUIDs generated by the creator (client or server job), never
--     by the database. No column has a uuid default.
--   * All times are UTC instants (timestamptz). Local time exists only as
--     review_log.utc_offset_min and the scheduler.* settings.
--   * Enumerations are text + CHECK (additive: a later migration may widen).
--   * app.* never has a foreign key into ref.* (soft references; the phone
--     holds only a subset of ref and dictionary entries can be retired).
--   * Learning-data rows are never hard-deleted: deleted_at is a tombstone.
--   * "clocks" is a JSON object {register name -> HLC string} used for
--     last-writer-wins; see SCHEMA.md section 3.
--   * Rows in learning-data tables are written only by the op-apply path.
-- =============================================================================

CREATE EXTENSION IF NOT EXISTS pg_trgm WITH SCHEMA public;

-- pg_trgm silently produces no trigrams for non-ASCII text when the database
-- LC_CTYPE is "C"/"POSIX". Japanese search would then return nothing, so fail
-- the migration loudly instead.
DO $$
BEGIN
  IF cardinality(public.show_trgm('日本語')) = 0 THEN
    RAISE EXCEPTION 'kotobaya: database LC_CTYPE (%) yields no trigrams for Japanese text; create the database with a UTF-8 ctype such as C.UTF-8 or en_US.UTF-8',
      (SELECT datctype FROM pg_database WHERE datname = current_database());
  END IF;
END $$;

CREATE SCHEMA ref;
CREATE SCHEMA app;

COMMENT ON SCHEMA ref IS 'Reference data (dictionary release). Read-only for clients; rewritten only by the dict-refresh job.';
COMMENT ON SCHEMA app IS 'Learning data (synced through ops), media content (server-built, snapshot-distributed) and system tables.';

-- =============================================================================
-- ref.* : reference data
-- =============================================================================

CREATE TABLE ref.dict_release (
  id          integer     PRIMARY KEY CHECK (id > 0),
  version     text        NOT NULL UNIQUE CHECK (version <> ''),
  built_at    timestamptz NOT NULL,
  loaded_at   timestamptz NOT NULL DEFAULT now(),
  is_current  boolean     NOT NULL DEFAULT false,
  sources     jsonb       NOT NULL DEFAULT '{}'::jsonb CHECK (jsonb_typeof(sources) = 'object'),
  artifacts   jsonb       NOT NULL DEFAULT '[]'::jsonb CHECK (jsonb_typeof(artifacts) = 'array')
);
CREATE UNIQUE INDEX dict_release_current_uq ON ref.dict_release (is_current) WHERE is_current;
COMMENT ON TABLE  ref.dict_release IS 'One row per dictionary release built by dict-refresh. Exactly one row has is_current = true once any release is loaded.';
COMMENT ON COLUMN ref.dict_release.id IS 'Monotonically increasing release number (1, 2, 3...). Higher = newer.';
COMMENT ON COLUMN ref.dict_release.version IS 'Human-readable version, e.g. 2026.11.0.';
COMMENT ON COLUMN ref.dict_release.sources IS 'Per-source provenance for the attribution page: {"jmdict":{"version":"2026-11-01","license":"CC BY-SA 4.0","url":"..."}, ...}.';
COMMENT ON COLUMN ref.dict_release.artifacts IS 'Downloadable device builds: [{"kind":"full|diff","scope":"top60k|all","from_release":null|int,"blob_hash":"<sha256>","size_bytes":int}].';

CREATE TABLE ref.dict_entry (
  seq                 bigint   PRIMARY KEY CHECK (seq > 0),
  language            text     NOT NULL DEFAULT 'ja',
  headword            text     NOT NULL CHECK (headword <> ''),
  headword_reading    text     NOT NULL CHECK (headword_reading <> ''),
  is_common           boolean  NOT NULL DEFAULT false,
  kanji_forms         jsonb    NOT NULL DEFAULT '[]'::jsonb CHECK (jsonb_typeof(kanji_forms) = 'array'),
  readings            jsonb    NOT NULL CHECK (jsonb_typeof(readings) = 'array' AND jsonb_array_length(readings) > 0),
  senses              jsonb    NOT NULL CHECK (jsonb_typeof(senses) = 'array'),
  pos                 text[]   NOT NULL DEFAULT '{}',
  misc                text[]   NOT NULL DEFAULT '{}',
  freq_rank           integer  CHECK (freq_rank > 0),
  added_release_id    integer  NOT NULL REFERENCES ref.dict_release (id),
  retired_release_id  integer  REFERENCES ref.dict_release (id)
);
CREATE INDEX dict_entry_freq_rank_idx ON ref.dict_entry (freq_rank) WHERE freq_rank IS NOT NULL;
COMMENT ON TABLE  ref.dict_entry IS 'One JMdict entry. Rows are never deleted: an entry dropped by JMdict gets retired_release_id set, so soft references from app.* keep resolving.';
COMMENT ON COLUMN ref.dict_entry.seq IS 'JMdict ent_seq. Stable across releases. This is the "entry id" used everywhere (app.note.entry_seq, app.word_status.entry_seq, ...).';
COMMENT ON COLUMN ref.dict_entry.language IS 'BCP 47 language of the headword. Always ja in v1.';
COMMENT ON COLUMN ref.dict_entry.headword IS 'Display form: first kanji form, or first reading for kana-only entries.';
COMMENT ON COLUMN ref.dict_entry.headword_reading IS 'First reading (kana). Equals headword for kana-only entries.';
COMMENT ON COLUMN ref.dict_entry.kanji_forms IS '[{"text":"食べる","common":true,"tags":[]}] in JMdict order; [] for kana-only entries.';
COMMENT ON COLUMN ref.dict_entry.readings IS '[{"text":"たべる","common":true,"tags":[],"applies_to":["*"]}] in JMdict order; applies_to lists kanji forms or "*".';
COMMENT ON COLUMN ref.dict_entry.senses IS '[{"pos":["v1","vt"],"misc":[],"field":[],"dialect":[],"info":[],"applies_to_kanji":["*"],"applies_to_kana":["*"],"gloss":[{"lang":"eng","text":"to eat"}],"xref":[]}].';
COMMENT ON COLUMN ref.dict_entry.pos IS 'Union of JMdict part-of-speech tags over all senses, e.g. {v1,vt}.';
COMMENT ON COLUMN ref.dict_entry.misc IS 'Union of JMdict misc tags over all senses, e.g. {uk}.';
COMMENT ON COLUMN ref.dict_entry.freq_rank IS 'Rank in the highest-priority ref.freq_list that contains the entry (1 = most frequent); NULL if in none. Defines "top 60k".';
COMMENT ON COLUMN ref.dict_entry.retired_release_id IS 'First release in which JMdict no longer contained this entry; NULL while live. Retired entries are excluded from search but still resolvable by seq.';

CREATE TABLE ref.dict_entry_form (
  seq     bigint   NOT NULL REFERENCES ref.dict_entry (seq) ON DELETE CASCADE,
  kind    text     NOT NULL CHECK (kind IN ('kanji', 'reading')),
  ord     smallint NOT NULL CHECK (ord >= 0),
  form    text     NOT NULL CHECK (form <> ''),
  norm    text     NOT NULL CHECK (norm <> ''),
  common  boolean  NOT NULL DEFAULT false,
  PRIMARY KEY (seq, kind, ord)
);
CREATE INDEX dict_entry_form_norm_prefix_idx ON ref.dict_entry_form (norm text_pattern_ops);
CREATE INDEX dict_entry_form_norm_trgm_idx   ON ref.dict_entry_form USING gin (norm public.gin_trgm_ops);
COMMENT ON TABLE  ref.dict_entry_form IS 'Search index: one row per kanji form and per reading of each entry (derived from dict_entry.kanji_forms / readings).';
COMMENT ON COLUMN ref.dict_entry_form.ord IS '0-based position within kanji_forms or readings.';
COMMENT ON COLUMN ref.dict_entry_form.form IS 'The form exactly as in JMdict.';
COMMENT ON COLUMN ref.dict_entry_form.norm IS 'Search key: NFKC, then katakana folded to hiragana. Queries are normalised the same way (romaji is converted to kana by the core before querying). Exact/prefix via the btree, substring (3+ chars) via the trigram index.';

CREATE TABLE ref.dict_entry_gloss (
  seq        bigint   NOT NULL REFERENCES ref.dict_entry (seq) ON DELETE CASCADE,
  sense_ord  smallint NOT NULL CHECK (sense_ord >= 0),
  gloss_ord  smallint NOT NULL CHECK (gloss_ord >= 0),
  lang       text     NOT NULL DEFAULT 'eng',
  gloss      text     NOT NULL CHECK (gloss <> ''),
  PRIMARY KEY (seq, sense_ord, gloss_ord)
);
CREATE INDEX dict_entry_gloss_trgm_idx ON ref.dict_entry_gloss USING gin (gloss public.gin_trgm_ops);
COMMENT ON TABLE ref.dict_entry_gloss IS 'Search index: one row per gloss (derived from dict_entry.senses). Search with ILIKE / % against gloss.';

CREATE TABLE ref.entry_kanji (
  seq      bigint NOT NULL REFERENCES ref.dict_entry (seq) ON DELETE CASCADE,
  literal  text   NOT NULL CHECK (char_length(literal) = 1),
  PRIMARY KEY (seq, literal)
);
CREATE INDEX entry_kanji_literal_idx ON ref.entry_kanji (literal);
COMMENT ON TABLE ref.entry_kanji IS 'Derived: each distinct kanji appearing in any kanji form of the entry. Backs the kanji: search term and the hot-kanji roll-up. literal need not exist in ref.kanji.';

CREATE TABLE ref.freq_list (
  id           text     PRIMARY KEY CHECK (id ~ '^[a-z0-9][a-z0-9_-]*$'),
  title        text     NOT NULL,
  priority     smallint NOT NULL UNIQUE CHECK (priority >= 0),
  entry_count  integer  NOT NULL DEFAULT 0 CHECK (entry_count >= 0),
  source       text
);
COMMENT ON TABLE  ref.freq_list IS 'One row per loaded frequency list (Yomitan frequency dictionary).';
COMMENT ON COLUMN ref.freq_list.id IS 'Stable slug, e.g. jpdb, bccwj, novels, netflix.';
COMMENT ON COLUMN ref.freq_list.priority IS '0 = primary list. dict_entry.freq_rank comes from the lowest-priority-number list containing the entry.';

CREATE TABLE ref.entry_freq (
  seq      bigint  NOT NULL REFERENCES ref.dict_entry (seq) ON DELETE CASCADE,
  list_id  text    NOT NULL REFERENCES ref.freq_list (id) ON DELETE CASCADE,
  rank     integer NOT NULL CHECK (rank > 0),
  PRIMARY KEY (seq, list_id)
);
CREATE INDEX entry_freq_list_rank_idx ON ref.entry_freq (list_id, rank);
COMMENT ON TABLE  ref.entry_freq IS 'Rank of an entry in a frequency list. One row per (entry, list): when a list ranks several forms of one entry, the best (smallest) rank is kept.';
COMMENT ON COLUMN ref.entry_freq.rank IS '1 = most frequent. Ranks may repeat and have gaps.';

CREATE TABLE ref.entry_pitch (
  seq        bigint     NOT NULL REFERENCES ref.dict_entry (seq) ON DELETE CASCADE,
  reading    text       NOT NULL CHECK (reading <> ''),
  positions  smallint[] NOT NULL CHECK (cardinality(positions) > 0),
  PRIMARY KEY (seq, reading)
);
COMMENT ON TABLE  ref.entry_pitch IS 'Pitch accent patterns (Kanjium) per reading of an entry.';
COMMENT ON COLUMN ref.entry_pitch.reading IS 'Kana reading exactly as in dict_entry.readings[].text.';
COMMENT ON COLUMN ref.entry_pitch.positions IS 'Downstep mora positions, most common first: 0 = heiban, 1 = atamadaka, n = drop after mora n. Example {0,2}.';

CREATE TABLE ref.kanji (
  literal       text     PRIMARY KEY CHECK (char_length(literal) = 1),
  on_readings   text[]   NOT NULL DEFAULT '{}',
  kun_readings  text[]   NOT NULL DEFAULT '{}',
  nanori        text[]   NOT NULL DEFAULT '{}',
  meanings      text[]   NOT NULL DEFAULT '{}',
  stroke_count  smallint CHECK (stroke_count > 0),
  grade         smallint CHECK (grade BETWEEN 1 AND 10),
  jlpt          smallint CHECK (jlpt BETWEEN 1 AND 5),
  freq_rank     integer  CHECK (freq_rank > 0),
  radical       text,
  components    text[]   NOT NULL DEFAULT '{}'
);
CREATE INDEX kanji_components_idx ON ref.kanji USING gin (components);
COMMENT ON TABLE  ref.kanji IS 'One kanji from KANJIDIC2, with components from KRADFILE.';
COMMENT ON COLUMN ref.kanji.literal IS 'The kanji itself, exactly one Unicode code point (may be outside the BMP).';
COMMENT ON COLUMN ref.kanji.on_readings IS 'On readings in katakana, KANJIDIC2 order.';
COMMENT ON COLUMN ref.kanji.kun_readings IS 'Kun readings in hiragana with KANJIDIC2 okurigana dots, e.g. た.べる.';
COMMENT ON COLUMN ref.kanji.meanings IS 'English meanings, KANJIDIC2 order.';
COMMENT ON COLUMN ref.kanji.grade IS 'KANJIDIC2 grade: 1-6 kyouiku, 8 jouyou, 9-10 jinmeiyou.';
COMMENT ON COLUMN ref.kanji.jlpt IS 'JLPT level as N-number (5 = easiest). KANJIDIC2 old levels 1-4 are mapped 4->5, 3->4, 2->2, 1->1; NULL if unknown.';
COMMENT ON COLUMN ref.kanji.freq_rank IS 'KANJIDIC2 newspaper frequency rank (1-2500).';
COMMENT ON COLUMN ref.kanji.components IS 'KRADFILE components (each one character), used for look-alike confusables and the Components card.';

CREATE TABLE ref.example_sentence (
  id              bigint PRIMARY KEY CHECK (id > 0),
  language        text   NOT NULL DEFAULT 'ja',
  text            text   NOT NULL CHECK (text <> ''),
  translation     text   NOT NULL,
  translation_id  bigint
);
CREATE INDEX example_sentence_text_trgm_idx ON ref.example_sentence USING gin (text public.gin_trgm_ops);
COMMENT ON TABLE  ref.example_sentence IS 'Tatoeba sentence pair (CC BY 2.0 FR).';
COMMENT ON COLUMN ref.example_sentence.id IS 'Tatoeba id of the Japanese sentence.';
COMMENT ON COLUMN ref.example_sentence.translation IS 'English translation; empty string if none.';
COMMENT ON COLUMN ref.example_sentence.translation_id IS 'Tatoeba id of the English sentence.';

CREATE TABLE ref.example_sentence_entry (
  sentence_id  bigint NOT NULL REFERENCES ref.example_sentence (id) ON DELETE CASCADE,
  seq          bigint NOT NULL REFERENCES ref.dict_entry (seq) ON DELETE CASCADE,
  PRIMARY KEY (sentence_id, seq)
);
CREATE INDEX example_sentence_entry_seq_idx ON ref.example_sentence_entry (seq);
COMMENT ON TABLE ref.example_sentence_entry IS 'Which dictionary entries occur in an example sentence ("linked entries").';

-- =============================================================================
-- app.* : shared types
-- =============================================================================

CREATE DOMAIN app.hlc AS text COLLATE "C"
  CHECK (VALUE ~ '^[0-9a-f]{12}-[0-9a-f]{4}-[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$');
COMMENT ON DOMAIN app.hlc IS 'Hybrid logical clock timestamp: <12 hex: wall-clock ms since epoch>-<4 hex: counter>-<device uuid, lowercase>. 54 chars. Byte-wise string order (COLLATE "C") is clock order and is a total order across devices.';

-- =============================================================================
-- app.* : system tables
-- =============================================================================

CREATE TABLE app.device (
  id             uuid        PRIMARY KEY,
  name           text        NOT NULL CHECK (name <> ''),
  kind           text        NOT NULL CHECK (kind IN ('android', 'web', 'script', 'server')),
  paired_at      timestamptz NOT NULL DEFAULT now(),
  last_seen_at   timestamptz,
  last_push_at   timestamptz,
  last_pull_seq  bigint      NOT NULL DEFAULT 0 CHECK (last_pull_seq >= 0),
  push_topic     text,
  revoked_at     timestamptz
);
COMMENT ON TABLE  app.device IS 'Every origin of sync ops: paired phones, web sessions, scripts, and the server itself. Rows are never deleted (change and review_log reference them). Not synced.';
COMMENT ON COLUMN app.device.kind IS 'server = the built-in row 00000000-0000-7000-8000-000000000001 used for ops emitted by server jobs (imports, merges, optimizer).';
COMMENT ON COLUMN app.device.last_pull_seq IS 'Highest change.seq this device has acknowledged pulling. Informational (sync-lag metric); the device is authoritative for its own cursor.';
COMMENT ON COLUMN app.device.push_topic IS 'ntfy/UnifiedPush topic or endpoint for server events; NULL if none.';
COMMENT ON COLUMN app.device.revoked_at IS 'Set when the device is revoked. Its tokens must be revoked in the same transaction. Ops already accepted stay.';

INSERT INTO app.device (id, name, kind) VALUES
  ('00000000-0000-7000-8000-000000000001', 'server', 'server');

CREATE TABLE app.api_token (
  id            uuid        PRIMARY KEY,
  name          text        NOT NULL CHECK (name <> ''),
  kind          text        NOT NULL CHECK (kind IN ('session', 'device', 'personal')),
  token_hash    text        NOT NULL UNIQUE CHECK (token_hash ~ '^[0-9a-f]{64}$'),
  token_prefix  text        NOT NULL DEFAULT '',
  scopes        text[]      NOT NULL CHECK (scopes <@ ARRAY['read', 'write', 'review', 'import', 'admin']::text[]),
  device_id     uuid        REFERENCES app.device (id),
  created_at    timestamptz NOT NULL DEFAULT now(),
  expires_at    timestamptz,
  last_used_at  timestamptz,
  revoked_at    timestamptz,
  CHECK (kind <> 'device' OR device_id IS NOT NULL)
);
CREATE INDEX api_token_device_idx ON app.api_token (device_id) WHERE device_id IS NOT NULL;
COMMENT ON TABLE  app.api_token IS 'Bearer credentials: web sessions, long-lived device tokens, and personal access tokens. Only the hash is stored. Not synced, never on device.';
COMMENT ON COLUMN app.api_token.name IS 'Audit name shown in logs and the token list, e.g. "Pixel 9", "coverage-script".';
COMMENT ON COLUMN app.api_token.token_hash IS 'Lowercase hex SHA-256 of the full token string. Tokens are high-entropy random, so no salt.';
COMMENT ON COLUMN app.api_token.token_prefix IS 'First 8 characters of the token, for display only.';
COMMENT ON COLUMN app.api_token.scopes IS 'Subset of {read,write,review,import,admin}. Sessions carry all five.';
COMMENT ON COLUMN app.api_token.device_id IS 'Device this token authenticates as; required for kind=device. Ops pushed with the token must carry this device id.';
COMMENT ON COLUMN app.api_token.expires_at IS 'NULL = never expires. A token is valid iff revoked_at IS NULL AND (expires_at IS NULL OR expires_at > now()).';

CREATE TABLE app.settings (
  key         text        PRIMARY KEY CHECK (key ~ '^[a-z][a-z0-9_]*(\.[a-z][a-z0-9_]*)*$'),
  value       jsonb       NOT NULL,
  hlc         app.hlc     NOT NULL,
  updated_at  timestamptz NOT NULL
);
COMMENT ON TABLE  app.settings IS 'User settings shared by all clients. One LWW register per key. Device-only preferences do not live here. Absent key = default (defaults live in the core).';
COMMENT ON COLUMN app.settings.key IS 'Dotted lowercase key, e.g. scheduler.day_rollover_hour. Well-known keys are listed in SCHEMA.md.';
COMMENT ON COLUMN app.settings.value IS 'Any JSON value. JSON null means "reset to default".';
COMMENT ON COLUMN app.settings.hlc IS 'HLC of the op that last won this key.';

CREATE TABLE app.fsrs_params (
  id                     uuid               PRIMARY KEY,
  name                   text               NOT NULL CHECK (name <> ''),
  desired_retention      double precision   NOT NULL DEFAULT 0.90 CHECK (desired_retention > 0 AND desired_retention < 1),
  maximum_interval_days  integer            NOT NULL DEFAULT 36500 CHECK (maximum_interval_days >= 1),
  learning_steps_s       integer[]          NOT NULL DEFAULT '{60,600}',
  relearning_steps_s     integer[]          NOT NULL DEFAULT '{600}',
  fuzz                   boolean            NOT NULL DEFAULT true,
  easy_days              double precision[] NOT NULL DEFAULT '{1,1,1,1,1,1,1}' CHECK (cardinality(easy_days) = 7),
  fsrs_version           text,
  weights                double precision[],
  weights_version        integer            NOT NULL DEFAULT 0 CHECK (weights_version >= 0),
  optimized_at           timestamptz,
  optimizer_stats        jsonb,
  created_at             timestamptz        NOT NULL,
  updated_at             timestamptz        NOT NULL,
  deleted_at             timestamptz,
  clocks                 jsonb              NOT NULL DEFAULT '{}'::jsonb CHECK (jsonb_typeof(clocks) = 'object'),
  CHECK ((weights IS NULL) = (fsrs_version IS NULL))
);
COMMENT ON TABLE  app.fsrs_params IS 'One row per scheduling preset: user-chosen configuration plus the optimizer-published FSRS weights.';
COMMENT ON COLUMN app.fsrs_params.id IS 'Preset id. 00000000-0000-7000-8000-000000000010 is the built-in Default preset and can never be deleted.';
COMMENT ON COLUMN app.fsrs_params.learning_steps_s IS 'Learning steps in seconds, in order; {} = no learning steps.';
COMMENT ON COLUMN app.fsrs_params.easy_days IS 'Load multiplier per ISO weekday, array index 1 = Monday ... 7 = Sunday. 1 = normal, 0.5 = reduced, 0 = minimum.';
COMMENT ON COLUMN app.fsrs_params.fsrs_version IS 'FSRS algorithm version the weights belong to, e.g. "6". NULL together with weights.';
COMMENT ON COLUMN app.fsrs_params.weights IS 'FSRS weights published by fsrs-optimize. NULL = use the core''s built-in default weights.';
COMMENT ON COLUMN app.fsrs_params.weights_version IS 'Incremented by each fsrs_params.published op; 0 = never optimized. Higher version wins.';
COMMENT ON COLUMN app.fsrs_params.optimizer_stats IS 'Metrics from the last optimizer run: {"review_count":int,"log_loss":number,"rmse_bins":number}.';
COMMENT ON COLUMN app.fsrs_params.clocks IS 'LWW registers: name, desired_retention, maximum_interval_days, learning_steps_s, relearning_steps_s, fuzz, easy_days, deleted.';

INSERT INTO app.fsrs_params (id, name, created_at, updated_at) VALUES
  ('00000000-0000-7000-8000-000000000010', 'Default', 'epoch', 'epoch');

CREATE TABLE app.change (
  seq              bigint      GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  op_id            uuid        NOT NULL UNIQUE,
  op_type          text        NOT NULL CHECK (op_type ~ '^[a-z][a-z0-9_]*(\.[a-z][a-z0-9_]*)+$'),
  op_version       smallint    NOT NULL DEFAULT 1 CHECK (op_version >= 1),
  entity_type      text        NOT NULL CHECK (entity_type <> ''),
  entity_id        text        NOT NULL CHECK (entity_id <> ''),
  device_id        uuid        NOT NULL REFERENCES app.device (id),
  hlc              app.hlc     NOT NULL,
  payload          jsonb       NOT NULL CHECK (jsonb_typeof(payload) = 'object'),
  caused_by_op_id  uuid,
  token_id         uuid,
  received_at      timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX change_entity_idx ON app.change (entity_type, entity_id, seq);
CREATE INDEX change_device_idx ON app.change (device_id, seq);
COMMENT ON TABLE  app.change IS 'The sync log: every accepted op, in the order the server applied it. Append-only; never updated, deleted, or compacted in v1. Server only.';
COMMENT ON COLUMN app.change.seq IS 'Server sequence number. Strictly increasing in commit order: the op-apply path MUST hold pg_advisory_xact_lock(7033001) from before the insert until commit, so a pull never sees seq n+1 before n. Gaps are allowed (rolled-back batches).';
COMMENT ON COLUMN app.change.op_id IS 'Client-generated op id (UUIDv7). The UNIQUE constraint is the idempotency key: a re-pushed op is skipped and reported as already applied.';
COMMENT ON COLUMN app.change.op_type IS 'Dotted op name, e.g. review.logged. The set of names is owned by contracts/sync.';
COMMENT ON COLUMN app.change.entity_type IS 'Table the op primarily targets, without schema, e.g. note, card, review_log, word_status.';
COMMENT ON COLUMN app.change.entity_id IS 'Primary key of the targeted row as text (uuid, entry seq, settings key, or composite joined with "|").';
COMMENT ON COLUMN app.change.device_id IS 'Origin device. Server-emitted ops use the built-in server device.';
COMMENT ON COLUMN app.change.hlc IS 'HLC assigned by the origin when the op was created.';
COMMENT ON COLUMN app.change.caused_by_op_id IS 'For ops the server emits as a consequence of another op (e.g. note.merged): the op_id that triggered it.';
COMMENT ON COLUMN app.change.token_id IS 'api_token.id that pushed the op (audit; no FK so tokens can be purged).';

CREATE FUNCTION app.reject_mutation() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
  RAISE EXCEPTION 'kotobaya: % on %.% is not allowed (append-only)', TG_OP, TG_TABLE_SCHEMA, TG_TABLE_NAME
    USING ERRCODE = 'restrict_violation';
END $$;
COMMENT ON FUNCTION app.reject_mutation() IS 'Trigger function enforcing append-only tables.';

CREATE TRIGGER change_append_only BEFORE UPDATE OR DELETE ON app.change
  FOR EACH ROW EXECUTE FUNCTION app.reject_mutation();

CREATE TABLE app.job (
  id                   uuid        PRIMARY KEY,
  kind                 text        NOT NULL CHECK (kind ~ '^[a-z][a-z0-9_-]*$'),
  status               text        NOT NULL DEFAULT 'queued' CHECK (status IN ('queued', 'running', 'succeeded', 'failed', 'cancelled')),
  payload              jsonb       NOT NULL DEFAULT '{}'::jsonb CHECK (jsonb_typeof(payload) = 'object'),
  result               jsonb,
  progress             real        NOT NULL DEFAULT 0 CHECK (progress >= 0 AND progress <= 1),
  progress_message     text,
  error                text,
  attempts             integer     NOT NULL DEFAULT 0 CHECK (attempts >= 0),
  max_attempts         integer     NOT NULL DEFAULT 3 CHECK (max_attempts >= 1),
  dedupe_key           text,
  run_after            timestamptz NOT NULL DEFAULT now(),
  locked_by            text,
  heartbeat_at         timestamptz,
  created_at           timestamptz NOT NULL DEFAULT now(),
  started_at           timestamptz,
  finished_at          timestamptz,
  created_by_token_id  uuid,
  CHECK ((status IN ('succeeded', 'failed', 'cancelled')) = (finished_at IS NOT NULL))
);
CREATE INDEX job_dequeue_idx ON app.job (run_after, created_at) WHERE status = 'queued';
CREATE INDEX job_created_idx ON app.job (created_at DESC);
CREATE UNIQUE INDEX job_dedupe_uq ON app.job (dedupe_key) WHERE dedupe_key IS NOT NULL AND status IN ('queued', 'running');
COMMENT ON TABLE  app.job IS 'Work queue between API and worker (no broker). Not in the spec table list but required by "the API enqueues heavy work in Postgres". Not synced.';
COMMENT ON COLUMN app.job.kind IS 'Job type slug: one of the API''s JobKind values (contracts/api/openapi.yaml): dict-refresh, media-import, media-parse, jpdb-deck-import, jpdb-history-import, fsrs-optimize, tts, deck-build. Payload and result shape per kind are owned by the API contract.';
COMMENT ON COLUMN app.job.status IS 'queued -> running -> succeeded|failed; queued|running -> cancelled. A failed attempt with attempts < max_attempts goes back to queued with a later run_after.';
COMMENT ON COLUMN app.job.dedupe_key IS 'Optional: at most one queued/running job per key (e.g. "media-parse:<media id>").';
COMMENT ON COLUMN app.job.locked_by IS 'Worker instance id holding the job while running. Dequeue: SELECT ... WHERE status=''queued'' AND run_after <= now() ORDER BY run_after, created_at FOR UPDATE SKIP LOCKED LIMIT 1.';
COMMENT ON COLUMN app.job.heartbeat_at IS 'Updated by the worker at least every 30 s while running; a running job with a heartbeat older than 5 min is considered stuck and may be re-queued.';

CREATE TABLE app.server_state (
  key         text        PRIMARY KEY CHECK (key ~ '^[a-z][a-z0-9_]*$'),
  value       text        NOT NULL,
  updated_at  timestamptz NOT NULL
);
COMMENT ON TABLE  app.server_state IS 'Server-only bookkeeping key/value store (the server''s counterpart of the device sync_state). Not synced, no op, not exposed through the API, never cleaned up. Keys are defined by the contracts; unknown keys are preserved. SCHEMA.md 4.4.';
COMMENT ON COLUMN app.server_state.key IS 'Defined keys: core_scheduler_version = the core scheduler version every card cache was last fully replayed with (opaque string, compared by equality). Absent or different from the running core''s => full replay of every maintained card cache under pg_advisory_xact_lock(7033001) before any push is applied; the key is written in that same transaction. contracts/sync/SYNC.md 10.5. log_epoch = the sync log''s epoch UUID (created by the server at startup if absent, replaced on restore). durable_seq = decimal, highest change.seq contained in the newest verified backup; written by the backup job only after the dump is verified, only if the dump''s log_epoch equals the live one, monotonically (greatest(old, new)); absent = 0. restore_pending = ''1'', written by the restore script into the restored database before the server starts; the server, at startup under pg_advisory_xact_lock(7033001), then sets a new log_epoch, durable_seq = max(change.seq), raises its HLC and deletes the key, all in one transaction. contracts/sync/SYNC.md 6.2-6.3.';

CREATE TABLE app.blob (
  hash          text        PRIMARY KEY CHECK (hash ~ '^[0-9a-f]{64}$'),
  size_bytes    bigint      NOT NULL CHECK (size_bytes >= 0),
  content_type  text        NOT NULL CHECK (content_type <> ''),
  kind          text        NOT NULL CHECK (kind IN ('audio', 'image', 'upload', 'snapshot')),
  origin        text        NOT NULL DEFAULT 'upload' CHECK (origin IN ('upload', 'clip', 'tts', 'cover', 'build')),
  created_at    timestamptz NOT NULL DEFAULT now()
);
COMMENT ON TABLE  app.blob IS 'One object in object storage, addressed by content hash. Rows are inserted after the object is durably stored. Not op-synced: clients fetch blobs by hash on demand.';
COMMENT ON COLUMN app.blob.hash IS 'Lowercase hex SHA-256 of the bytes. Also the object key. References to blobs elsewhere (*_blob_hash columns, [sound:<hash>] in note fields) are soft.';
COMMENT ON COLUMN app.blob.kind IS 'audio, image = card/media assets; upload = raw import file; snapshot = dictionary or media snapshot archive.';
COMMENT ON COLUMN app.blob.origin IS 'upload = user/client supplied, clip = cut from uploaded media, tts = VOICEVOX, cover = media cover art, build = produced by a server job.';

-- =============================================================================
-- app.* : learning data (synced through ops)
-- =============================================================================

CREATE TABLE app.grammar_point (
  id               uuid        PRIMARY KEY,
  language         text        NOT NULL DEFAULT 'ja',
  title            text        NOT NULL CHECK (title <> ''),
  pattern          text        NOT NULL DEFAULT '',
  meaning          text        NOT NULL DEFAULT '',
  explanation      text        NOT NULL DEFAULT '',
  notes            text        NOT NULL DEFAULT '',
  jlpt             smallint    CHECK (jlpt BETWEEN 1 AND 5),
  detection_rules  jsonb       NOT NULL DEFAULT '[]'::jsonb CHECK (jsonb_typeof(detection_rules) = 'array'),
  related_ids      uuid[]      NOT NULL DEFAULT '{}',
  links            jsonb       NOT NULL DEFAULT '[]'::jsonb CHECK (jsonb_typeof(links) = 'array'),
  is_stub          boolean     NOT NULL DEFAULT false,
  created_at       timestamptz NOT NULL,
  updated_at       timestamptz NOT NULL,
  deleted_at       timestamptz,
  clocks           jsonb       NOT NULL DEFAULT '{}'::jsonb CHECK (jsonb_typeof(clocks) = 'object')
);
CREATE INDEX grammar_point_search_trgm_idx ON app.grammar_point USING gin ((title || ' ' || pattern) public.gin_trgm_ops);
COMMENT ON TABLE  app.grammar_point IS 'The user''s grammar library. The spec lists it under reference data, but it is user-authored and created offline, so it lives in app.* and syncs through ops (see SUMMARY.md).';
COMMENT ON COLUMN app.grammar_point.pattern IS 'Display pattern, e.g. 〜ざるを得ない.';
COMMENT ON COLUMN app.grammar_point.explanation IS 'Markdown.';
COMMENT ON COLUMN app.grammar_point.notes IS 'Register and nuance notes, Markdown.';
COMMENT ON COLUMN app.grammar_point.jlpt IS 'N-level 1-5 (5 easiest); NULL if unclassified.';
COMMENT ON COLUMN app.grammar_point.detection_rules IS 'Whole-array LWW register: [{"rule":"[verb:未然形] ざる を 得 ない","draft":false}] in the token-pattern language; [] = not auto-detected.';
COMMENT ON COLUMN app.grammar_point.related_ids IS 'Ids of related grammar points (soft references; may point at deleted points).';
COMMENT ON COLUMN app.grammar_point.links IS '[{"title":"DoJG p.123","url":"https://..."}].';
COMMENT ON COLUMN app.grammar_point.is_stub IS 'true for seeded pattern-and-title-only points not yet filled in.';
COMMENT ON COLUMN app.grammar_point.clocks IS 'LWW registers: title, pattern, meaning, explanation, notes, jlpt, detection_rules, related_ids, links, is_stub, deleted.';

CREATE TABLE app.note_type (
  id          uuid        PRIMARY KEY,
  name        text        NOT NULL CHECK (name <> ''),
  base_type   text        NOT NULL CHECK (base_type IN ('vocab', 'kanji', 'phrase', 'grammar', 'sentence', 'custom')),
  builtin     boolean     NOT NULL DEFAULT false,
  fields      jsonb       NOT NULL CHECK (jsonb_typeof(fields) = 'array'),
  templates   jsonb       NOT NULL CHECK (jsonb_typeof(templates) = 'object'),
  css         text        NOT NULL DEFAULT '',
  created_at  timestamptz NOT NULL,
  updated_at  timestamptz NOT NULL,
  deleted_at  timestamptz,
  clocks      jsonb       NOT NULL DEFAULT '{}'::jsonb CHECK (jsonb_typeof(clocks) = 'object'),
  UNIQUE (id, base_type),
  CHECK (NOT (builtin AND deleted_at IS NOT NULL))
);
COMMENT ON TABLE  app.note_type IS 'Field definitions and card templates. Six built-ins (seeded below, fixed ids) plus user-defined types.';
COMMENT ON COLUMN app.note_type.base_type IS 'Which of the six note types this is. Immutable after creation. Decides which reference column a note may use and which built-in card kinds exist.';
COMMENT ON COLUMN app.note_type.builtin IS 'Built-ins cannot be deleted and their field keys cannot be removed; name, templates and css may be edited.';
COMMENT ON COLUMN app.note_type.fields IS 'Ordered field definitions: [{"key":"expression","label":"Expression","kind":"text|audio|image"}]. key matches ^[a-z][a-z0-9_]*$ and is unique within the type; keys are never renamed (add a new one instead).';
COMMENT ON COLUMN app.note_type.templates IS 'Card kinds: {"<kind>":{"default":true,"front":"<html>"|null,"back":"<html>"|null}}. kind matches ^[a-z][a-z0-9_]*$. default = create this card automatically with a new note. front/back null = use the core''s built-in template for (base_type, kind). Placeholders are {{field_key}}.';
COMMENT ON COLUMN app.note_type.css IS 'Extra CSS appended after assets/card/ CSS.';
COMMENT ON COLUMN app.note_type.clocks IS 'LWW registers: name, fields, css, deleted, and one per card kind: templates.<kind>.';

