CREATE FUNCTION app.note_search_text(fields jsonb, mnemonic text, source_sentence text)
RETURNS text LANGUAGE sql IMMUTABLE PARALLEL SAFE
RETURN coalesce((SELECT string_agg(e.value, ' ' ORDER BY e.key) FROM jsonb_each_text(fields) AS e), '')
       || ' ' || coalesce(mnemonic, '') || ' ' || coalesce(source_sentence, '');
COMMENT ON FUNCTION app.note_search_text(jsonb, text, text) IS 'Concatenation of all note field values (key order), mnemonic and source sentence; feeds note.search_text.';

CREATE TABLE app.note (
  id                    uuid        PRIMARY KEY,
  note_type_id          uuid        NOT NULL,
  type                  text        NOT NULL,
  language              text        NOT NULL DEFAULT 'ja',
  entry_seq             bigint      CHECK (entry_seq > 0),
  kanji_literal         text        CHECK (char_length(kanji_literal) = 1),
  grammar_point_id      uuid        REFERENCES app.grammar_point (id),
  fields                jsonb       NOT NULL DEFAULT '{}'::jsonb CHECK (jsonb_typeof(fields) = 'object'),
  tags                  text[]      NOT NULL DEFAULT '{}',
  mnemonic              text        NOT NULL DEFAULT '',
  source_sentence       text        NOT NULL DEFAULT '',
  source_sentence_id    uuid,
  source_media_id       uuid,
  origin                text        NOT NULL DEFAULT 'manual' CHECK (origin ~ '^[a-z][a-z0-9_]*$'),
  created_by_device_id  uuid        NOT NULL REFERENCES app.device (id),
  created_at            timestamptz NOT NULL,
  updated_at            timestamptz NOT NULL,
  deleted_at            timestamptz,
  merged_into_id        uuid        REFERENCES app.note (id),
  clocks                jsonb       NOT NULL DEFAULT '{}'::jsonb CHECK (jsonb_typeof(clocks) = 'object'),
  search_text           text        GENERATED ALWAYS AS (app.note_search_text(fields, mnemonic, source_sentence)) STORED,
  FOREIGN KEY (note_type_id, type) REFERENCES app.note_type (id, base_type),
  CHECK (entry_seq IS NULL OR type = 'vocab'),
  CHECK (kanji_literal IS NULL OR type = 'kanji'),
  CHECK (grammar_point_id IS NULL OR type = 'grammar'),
  CHECK (merged_into_id IS NULL OR (deleted_at IS NOT NULL AND merged_into_id <> id))
);
-- "Words are learned once, globally": at most one live note per referenced thing.
-- Server-only uniqueness; the device schema has plain indexes (SCHEMA.md 4.2).
-- Op-apply must never let these indexes reject an op: an op that would create a
-- second live row runs the merge procedure instead (SCHEMA.md 4.2).
CREATE UNIQUE INDEX note_live_entry_uq   ON app.note (entry_seq)        WHERE entry_seq IS NOT NULL        AND deleted_at IS NULL;
CREATE UNIQUE INDEX note_live_kanji_uq   ON app.note (kanji_literal)    WHERE kanji_literal IS NOT NULL    AND deleted_at IS NULL;
CREATE UNIQUE INDEX note_live_grammar_uq ON app.note (grammar_point_id) WHERE grammar_point_id IS NOT NULL AND deleted_at IS NULL;
CREATE INDEX note_type_idx        ON app.note (note_type_id);
CREATE INDEX note_tags_idx        ON app.note USING gin (tags);
CREATE INDEX note_search_trgm_idx ON app.note USING gin (search_text public.gin_trgm_ops);
CREATE INDEX note_updated_idx     ON app.note (updated_at);
CREATE INDEX note_merged_into_idx ON app.note (merged_into_id) WHERE merged_into_id IS NOT NULL;
COMMENT ON TABLE  app.note IS 'One thing being learned. Cards hang off a note.';
COMMENT ON COLUMN app.note.type IS 'vocab|kanji|phrase|grammar|sentence|custom. Always equals note_type.base_type (composite FK). Immutable.';
COMMENT ON COLUMN app.note.note_type_id IS 'Immutable after creation in v1.';
COMMENT ON COLUMN app.note.language IS 'BCP 47; always ja in v1.';
COMMENT ON COLUMN app.note.entry_seq IS 'Soft reference to ref.dict_entry.seq; only for type=vocab. NULL for a vocab note that matched no JMdict entry. Plain LWW register "entry_seq" (NULL -> value on a late match, value -> other value on a re-match, value -> NULL). Any op that makes it equal to another live note''s entry_seq triggers the merge procedure with this note as the loser (SCHEMA.md 4.2). A JMdict expression is a vocab note; type=phrase is for free-form phrases without an entry.';
COMMENT ON COLUMN app.note.kanji_literal IS 'Soft reference to ref.kanji.literal; only for type=kanji. Immutable.';
COMMENT ON COLUMN app.note.grammar_point_id IS 'Grammar point this note studies; only for type=grammar. Immutable.';
COMMENT ON COLUMN app.note.fields IS 'Object {field key -> string}. Keys come from note_type.fields; unknown keys are preserved, missing keys mean "". Values are HTML fragments; media as [sound:<sha256>] and <img src="blob:<sha256>">. For referenced notes an empty field means "render from the dictionary". Each key is its own LWW register.';
COMMENT ON COLUMN app.note.tags IS 'Set of tags (no duplicates, no whitespace, case-sensitive), sorted ascending. One LWW register for the whole set (concurrent edits on two devices: the later set wins whole; known trade-off, SUMMARY.md). "leech" is NOT stored here; it is derived from card.lapses.';
COMMENT ON COLUMN app.note.mnemonic IS 'User mnemonic (Markdown); shown on the card while the word is hot.';
COMMENT ON COLUMN app.note.source_sentence IS 'Sentence the note was mined from, copied by value so it survives media deletion and works on devices without the media. "" if none.';
COMMENT ON COLUMN app.note.source_sentence_id IS 'Soft reference to app.sentence.id when mined from imported media; may dangle.';
COMMENT ON COLUMN app.note.source_media_id IS 'Soft reference to app.media.id; may dangle.';
COMMENT ON COLUMN app.note.origin IS 'How the note was created: manual, takoboto, yomitan, ankiconnect, share, reader, deck, jpdb_import, api, auto_kanji. Open set. Immutable.';
COMMENT ON COLUMN app.note.deleted_at IS 'Tombstone. Deletion is permanent: later or concurrent edits still merge into the row but never clear deleted_at. A deleted note hides all its cards.';
COMMENT ON COLUMN app.note.merged_into_id IS 'Set only by the server''s note.merged op when two live notes referenced the same entry/kanji/grammar point: this (losing) note is tombstoned and points at the surviving note. Never a chain: always the final survivor. Permanent. Register ops addressed to this row are also applied to the survivor (SCHEMA.md 4.2).';
COMMENT ON COLUMN app.note.clocks IS 'LWW registers: fields.<key> (one per field key), tags, mnemonic, source_sentence (covers source_sentence_id and source_media_id too), entry_seq, deleted. Forwarded to the survivor on merge: all except entry_seq and deleted.';
COMMENT ON COLUMN app.note.search_text IS 'Generated. Substring search target (pg_trgm).';

CREATE TABLE app.card (
  id               uuid             PRIMARY KEY,
  note_id          uuid             NOT NULL REFERENCES app.note (id),
  kind             text             NOT NULL CHECK (kind ~ '^[a-z][a-z0-9_]*$'),
  preset_id        uuid             NOT NULL DEFAULT '00000000-0000-7000-8000-000000000010' REFERENCES app.fsrs_params (id),
  -- user registers (LWW, synced)
  suspended        boolean          NOT NULL DEFAULT false,
  buried_until     timestamptz,
  flags            smallint         NOT NULL DEFAULT 0 CHECK (flags BETWEEN 0 AND 7),
  -- schedule cache (derived from review_log; never synced)
  state            text             NOT NULL DEFAULT 'new' CHECK (state IN ('new', 'learning', 'review', 'relearning')),
  step             smallint         CHECK (step >= 0),
  stability        double precision CHECK (stability > 0),
  difficulty       double precision CHECK (difficulty >= 1 AND difficulty <= 10),
  due_at           timestamptz,
  interval_days    integer          CHECK (interval_days >= 0),
  last_review_at   timestamptz,
  last_review_id   uuid,
  reps             integer          NOT NULL DEFAULT 0 CHECK (reps >= 0),
  lapses           integer          NOT NULL DEFAULT 0 CHECK (lapses >= 0),
  weights_version  integer          NOT NULL DEFAULT 0 CHECK (weights_version >= 0),
  -- lifecycle
  created_at       timestamptz      NOT NULL,
  updated_at       timestamptz      NOT NULL,
  deleted_at       timestamptz,
  merged_into_id   uuid             REFERENCES app.card (id),
  clocks           jsonb            NOT NULL DEFAULT '{}'::jsonb CHECK (jsonb_typeof(clocks) = 'object'),
  CHECK ((state = 'new') = (due_at IS NULL)),
  CHECK (state <> 'new' OR (stability IS NULL AND difficulty IS NULL AND step IS NULL)),
  CHECK (merged_into_id IS NULL OR (deleted_at IS NOT NULL AND merged_into_id <> id))
);
-- One live card per (note, kind). Server-only uniqueness; plain index on device.
CREATE UNIQUE INDEX card_live_note_kind_uq ON app.card (note_id, kind) WHERE deleted_at IS NULL;
CREATE INDEX card_note_idx        ON app.card (note_id);
CREATE INDEX card_due_idx         ON app.card (due_at) WHERE deleted_at IS NULL AND NOT suspended AND state <> 'new';
CREATE INDEX card_new_idx         ON app.card (created_at) WHERE deleted_at IS NULL AND NOT suspended AND state = 'new';
CREATE INDEX card_lapses_idx      ON app.card (lapses) WHERE deleted_at IS NULL AND lapses > 0;
CREATE INDEX card_merged_into_idx ON app.card (merged_into_id) WHERE merged_into_id IS NOT NULL;
COMMENT ON TABLE  app.card IS 'One reviewable face of a note. The schedule columns are a cache rebuilt by replaying review_log; only the user registers and lifecycle columns are changed by ops.';
COMMENT ON COLUMN app.card.kind IS 'A key of note_type.templates, e.g. meaning, reading, listening, cloze. Immutable.';
COMMENT ON COLUMN app.card.preset_id IS 'Scheduling preset (LWW register "preset_id"). Points at the Default preset unless changed. If the preset is tombstoned, schedule with Default.';
COMMENT ON COLUMN app.card.suspended IS 'LWW register "suspended". Suspended cards are never queued but keep their schedule.';
COMMENT ON COLUMN app.card.buried_until IS 'LWW register "buried_until": manual bury; the card is hidden while now < buried_until. NULL = not buried. Sibling burying is NOT stored here: the queue builder derives it from review_log.';
COMMENT ON COLUMN app.card.flags IS 'LWW register "flags": 0 = none, 1-7 = user flag colour.';
COMMENT ON COLUMN app.card.state IS 'Cache. new = no schedule-feeding review yet (or reset).';
COMMENT ON COLUMN app.card.step IS 'Cache. Index into the preset''s (re)learning steps while state is learning/relearning; else NULL.';
COMMENT ON COLUMN app.card.stability IS 'Cache. FSRS stability in days.';
COMMENT ON COLUMN app.card.difficulty IS 'Cache. FSRS difficulty, 1-10.';
COMMENT ON COLUMN app.card.due_at IS 'Cache. Instant the card becomes due; NULL iff state = new.';
COMMENT ON COLUMN app.card.interval_days IS 'Cache. Interval scheduled by the last review (0 during learning steps).';
COMMENT ON COLUMN app.card.last_review_at IS 'Cache. reviewed_at of the last RATED (scheduled/learning) row of the replay set, in (reviewed_at, hlc, id) order; the base for FSRS elapsed time. Manual set_due rows leave it unchanged (last_review_id may then name the manual row); a manual reset row sets it to NULL (card is new again). NULL if no rated row. Fold still equals full replay under this rule. SCHEMA.md 4.2.';
COMMENT ON COLUMN app.card.last_review_id IS 'Cache. review_log.id of the last row folded into this cache (scheduled, learning or manual). Lets a replica detect out-of-order arrivals: a newly applied review ordered before this one in (reviewed_at, hlc, id) order forces a full replay of the card.';
COMMENT ON COLUMN app.card.reps IS 'Cache. Number of replayed scheduled/learning reviews.';
COMMENT ON COLUMN app.card.lapses IS 'Cache. Number of Again ratings given while state was review. Leech = lapses >= scheduler.leech_threshold.';
COMMENT ON COLUMN app.card.weights_version IS 'Cache. fsrs_params.weights_version used for the last replay; a mismatch with the preset means the cache is stale and must be replayed.';
COMMENT ON COLUMN app.card.deleted_at IS 'Tombstone (permanent). Reviews of a deleted card stay in review_log.';
COMMENT ON COLUMN app.card.merged_into_id IS 'Set only by the server''s card.merged op: this card lost a (note, kind) collision; its reviews replay as part of the surviving card. Never a chain. Permanent. Register ops addressed to this row are also applied to the survivor.';
COMMENT ON COLUMN app.card.clocks IS 'LWW registers: suspended, buried_until, flags, preset_id, deleted. Forwarded to the survivor on merge: all except deleted.';

CREATE TABLE app.review_log (
  id              uuid        PRIMARY KEY,
  card_id         uuid        NOT NULL REFERENCES app.card (id),
  device_id       uuid        NOT NULL REFERENCES app.device (id),
  hlc             app.hlc     NOT NULL,
  reviewed_at     timestamptz NOT NULL,
  utc_offset_min  smallint    CHECK (utc_offset_min BETWEEN -1080 AND 1080),
  review_type     text        NOT NULL CHECK (review_type IN ('scheduled', 'learning', 'drill', 'cram', 'manual')),
  rating          smallint    CHECK (rating BETWEEN 1 AND 4),
  button          text        CHECK (button IN ('again', 'hard', 'good', 'easy', 'nothing', 'something', 'okay')),
  duration_ms     integer     CHECK (duration_ms >= 0),
  manual_action   text        CHECK (manual_action IN ('set_due', 'reset')),
  manual_due_at   timestamptz,
  sentence_id     uuid,
  import_source   text,
  undone_at       timestamptz,
  undone_hlc      app.hlc,
  CHECK ((review_type = 'manual') = (rating IS NULL)),
  CHECK ((review_type = 'manual') = (manual_action IS NOT NULL)),
  CHECK ((manual_action IS NOT DISTINCT FROM 'set_due') = (manual_due_at IS NOT NULL)),
  CHECK (button IS NULL OR rating = CASE button
           WHEN 'again' THEN 1 WHEN 'nothing' THEN 1 WHEN 'something' THEN 1
           WHEN 'hard' THEN 2 WHEN 'good' THEN 3 WHEN 'okay' THEN 3 WHEN 'easy' THEN 4 END),
  CHECK ((undone_at IS NULL) = (undone_hlc IS NULL))
);
CREATE INDEX review_log_card_idx     ON app.review_log (card_id, hlc, id);
CREATE INDEX review_log_replay_idx   ON app.review_log (card_id, reviewed_at, hlc, id);
CREATE INDEX review_log_reviewed_idx ON app.review_log (reviewed_at);
CREATE INDEX review_log_device_idx   ON app.review_log (device_id, hlc);
COMMENT ON TABLE  app.review_log IS 'Source of truth for scheduling. Append-only: a row is inserted once by review.logged and afterwards only undone_at/undone_hlc may change (set, or lowered to an earlier undo; never cleared). Never deleted. Enforced by trigger review_log_append_only.';
COMMENT ON COLUMN app.review_log.id IS 'UUIDv7 from the reviewing client. Inserting an existing id is a no-op (idempotent).';
COMMENT ON COLUMN app.review_log.card_id IS 'Card as it was on the reviewing device. Never rewritten, even if that card is later merged or deleted.';
COMMENT ON COLUMN app.review_log.hlc IS 'Replay tie-breaker. A card''s reviews are replayed in (reviewed_at, hlc, id) order (SYNC.md 9.1). Equals the HLC of the review.logged op, except imported history, where it is synthesised from the historical time.';
COMMENT ON COLUMN app.review_log.reviewed_at IS 'Wall-clock instant on the reviewing device; used for elapsed-time maths and stats. Primary replay order key: a card''s reviews are replayed in (reviewed_at, hlc, id) order (SYNC.md 9.1), so elapsed time is never negative (still clamped to >= 0). May disagree with hlc order under clock skew.';
COMMENT ON COLUMN app.review_log.utc_offset_min IS 'Device UTC offset in minutes when the review happened (e.g. 540 for JST); for local-day stats only. NULL = unknown (imports, clients that cannot tell): readers fall back to scheduler.timezone. Native clients MUST send it.';
COMMENT ON COLUMN app.review_log.review_type IS 'scheduled, learning: feed FSRS. drill, cram: logged only, never change the schedule. manual: a reschedule/reset (addition to the spec list; see SUMMARY.md).';
COMMENT ON COLUMN app.review_log.rating IS 'FSRS rating 1 Again, 2 Hard, 3 Good, 4 Easy. NULL iff review_type = manual.';
COMMENT ON COLUMN app.review_log.button IS 'Button actually pressed. Five-button mode: nothing, something (both rating 1), hard, okay (rating 3), easy. NULL when unknown (imports) or manual.';
COMMENT ON COLUMN app.review_log.duration_ms IS 'Time from card shown to answer; NULL when unknown. Clients cap at 600000.';
COMMENT ON COLUMN app.review_log.manual_action IS 'For review_type = manual: set_due = keep memory state, set due_at := manual_due_at; reset = card returns to state new.';
COMMENT ON COLUMN app.review_log.sentence_id IS 'Sentence shown for rotating-example cards (soft reference to app.sentence.id or NULL).';
COMMENT ON COLUMN app.review_log.import_source IS 'NULL for native reviews; "jpdb" for imported history.';
COMMENT ON COLUMN app.review_log.undone_at IS 'Wall-clock time of the winning review.undone op. Undone rows are skipped by replay and stats. An undo cannot be undone.';
COMMENT ON COLUMN app.review_log.undone_hlc IS 'HLC of the winning review.undone op. If several undo ops target one review, the SMALLEST hlc wins on every replica (apply iff undone_hlc IS NULL OR op.hlc < undone_hlc), so the result does not depend on arrival order.';

CREATE FUNCTION app.review_log_guard() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
  IF TG_OP = 'DELETE' THEN
    RAISE EXCEPTION 'kotobaya: review_log is append-only (DELETE)' USING ERRCODE = 'restrict_violation';
  END IF;
  IF (to_jsonb(NEW) - 'undone_at' - 'undone_hlc') IS DISTINCT FROM (to_jsonb(OLD) - 'undone_at' - 'undone_hlc') THEN
    RAISE EXCEPTION 'kotobaya: review_log is append-only (only undone_at/undone_hlc may change)' USING ERRCODE = 'restrict_violation';
  END IF;
  IF NEW.undone_hlc IS NULL OR (OLD.undone_hlc IS NOT NULL AND NEW.undone_hlc >= OLD.undone_hlc) THEN
    RAISE EXCEPTION 'kotobaya: review_log undo may only be set or lowered' USING ERRCODE = 'restrict_violation';
  END IF;
  RETURN NEW;
END $$;
COMMENT ON FUNCTION app.review_log_guard() IS 'Trigger function: review_log rows are immutable except for a first or earlier undo.';

CREATE TRIGGER review_log_append_only BEFORE UPDATE OR DELETE ON app.review_log
  FOR EACH ROW EXECUTE FUNCTION app.review_log_guard();

CREATE TABLE app.word_status (
  entry_seq        bigint      PRIMARY KEY CHECK (entry_seq > 0),
  status           text        NOT NULL CHECK (status IN ('new', 'learning', 'known', 'never_forget', 'blacklisted', 'ignored')),
  auto_status      text        CHECK (auto_status IN ('new', 'learning', 'known')),
  override_status  text        CHECK (override_status IN ('known', 'never_forget', 'blacklisted', 'ignored')),
  override_hlc     app.hlc,
  override_origin  text        CHECK (override_origin IN ('manual', 'jpdb_import')),
  updated_at       timestamptz NOT NULL,
  CHECK (status = coalesce(override_status, auto_status, 'new')),
  CHECK (override_status IS NULL OR override_hlc IS NOT NULL)
);
CREATE INDEX word_status_status_idx ON app.word_status (status);
COMMENT ON TABLE  app.word_status IS 'Per dictionary entry: what the user knows. Absent row = new. Drives coverage.';
COMMENT ON COLUMN app.word_status.entry_seq IS 'Soft reference to ref.dict_entry.seq.';
COMMENT ON COLUMN app.word_status.status IS 'Effective status = coalesce(override_status, auto_status, new). Maintained by whoever writes the other two columns (CHECK enforces it).';
COMMENT ON COLUMN app.word_status.auto_status IS 'Derived on every replica from the entry''s vocab note cards (rule owned by the core); never synced. NULL = no live vocab note.';
COMMENT ON COLUMN app.word_status.override_status IS 'Explicit user/import override: one LWW register with override_hlc. NULL with a non-NULL override_hlc = override cleared (the clear must still win against older sets).';
COMMENT ON COLUMN app.word_status.override_hlc IS 'HLC of the word.status_set / word.status_cleared op that last won.';
COMMENT ON COLUMN app.word_status.override_origin IS 'Who set the current override; NULL when there is none.';

CREATE TABLE app.deck (
  id                 uuid        PRIMARY KEY,
  name               text        NOT NULL CHECK (name <> ''),
  type               text        NOT NULL CHECK (type IN ('user', 'media', 'list', 'smart')),
  language           text        NOT NULL DEFAULT 'ja',
  priority           integer     NOT NULL DEFAULT 0,
  enabled            boolean     NOT NULL DEFAULT true,
  new_cards_per_day  integer     CHECK (new_cards_per_day >= 0),
  reviews_per_day    integer     CHECK (reviews_per_day >= 0),
  settings           jsonb       NOT NULL DEFAULT '{}'::jsonb CHECK (jsonb_typeof(settings) = 'object'),
  media_id           uuid,
  list_key           text,
  query              text,
  content_version    integer     NOT NULL DEFAULT 0 CHECK (content_version >= 0),
  content_blob_hash  text        CHECK (content_blob_hash ~ '^[0-9a-f]{64}$'),
  created_at         timestamptz NOT NULL,
  updated_at         timestamptz NOT NULL,
  deleted_at         timestamptz,
  clocks             jsonb       NOT NULL DEFAULT '{}'::jsonb CHECK (jsonb_typeof(clocks) = 'object'),
  CHECK ((type = 'media') = (media_id IS NOT NULL)),
  CHECK (media_id IS NULL OR id = media_id),
  CHECK ((type = 'list')  = (list_key IS NOT NULL)),
  CHECK ((type = 'smart') = (query IS NOT NULL))
);
CREATE UNIQUE INDEX deck_live_media_uq ON app.deck (media_id) WHERE media_id IS NOT NULL AND deleted_at IS NULL;
CREATE UNIQUE INDEX deck_live_list_uq  ON app.deck (list_key) WHERE list_key IS NOT NULL AND deleted_at IS NULL;
CREATE INDEX deck_priority_idx ON app.deck (priority, id) WHERE deleted_at IS NULL;
COMMENT ON TABLE  app.deck IS 'A source of new cards and a coverage target. Cards are not "in" decks: words are learned once, globally.';
COMMENT ON COLUMN app.deck.name IS 'Not unique.';
COMMENT ON COLUMN app.deck.type IS 'user = hand-built; media = generated 1:1 from app.media; list = generated list (JLPT, frequency); smart = saved card-search query. Immutable. deck.created for media and list decks is emitted ONLY by the server (their content is server-built anyway); a client-originated one is rejected. Clients create user and smart decks, which have no natural key and so cannot collide.';
COMMENT ON COLUMN app.deck.id IS 'UUIDv7 for user/smart/list decks. A media deck reuses its media''s id (id = media_id), so retried import jobs are idempotent.';
COMMENT ON COLUMN app.deck.priority IS 'New cards are drawn from enabled decks in ascending (priority, id) order. Duplicates allowed; id breaks ties.';
COMMENT ON COLUMN app.deck.enabled IS 'false = deck supplies no new cards (still shows coverage).';
COMMENT ON COLUMN app.deck.new_cards_per_day IS 'Per-deck daily new-card limit; NULL = only the global limit applies.';
COMMENT ON COLUMN app.deck.reviews_per_day IS 'Per-deck daily review limit; NULL = only the global limit applies.';
COMMENT ON COLUMN app.deck.settings IS 'Open object, each top-level key its own LWW register "settings.<key>". Known keys: order ("deck_frequency"|"global_frequency"|"position"|"chronological"; default deck_frequency for media, position otherwise), add_kanji ("off"|"before"|"alongside"), card_kinds (array of card kinds to create, overriding note-type defaults).';
COMMENT ON COLUMN app.deck.media_id IS 'Soft reference to app.media.id; set iff type = media, and then equal to deck.id. Immutable.';
COMMENT ON COLUMN app.deck.list_key IS 'Set iff type = list. Slug of the generated list, e.g. jlpt-n3, freq-jpdb-5000. Immutable. The server creates at most one live deck per list_key: enabling a list that already has a live deck returns that deck and emits nothing.';
COMMENT ON COLUMN app.deck.query IS 'Set iff type = smart. Card search-language string. LWW register "query".';
COMMENT ON COLUMN app.deck.content_version IS 'For media/list decks: version of the server-generated deck_item set, bumped by deck.content_published. Clients holding a lower version download the deck snapshot. Always 0 for user/smart decks.';
COMMENT ON COLUMN app.deck.content_blob_hash IS 'Blob holding the deck_item snapshot for content_version; NULL when content_version = 0.';
COMMENT ON COLUMN app.deck.clocks IS 'LWW registers: name, priority, enabled, new_cards_per_day, reviews_per_day, query, settings.<key>, deleted.';

CREATE TABLE app.deck_item (
  deck_id           uuid        NOT NULL REFERENCES app.deck (id),
  item_key          text        NOT NULL,
  entry_seq         bigint      CHECK (entry_seq > 0),
  note_id           uuid        REFERENCES app.note (id),
  position          bigint      NOT NULL DEFAULT 0,
  occurrence_count  integer     NOT NULL DEFAULT 0 CHECK (occurrence_count >= 0),
  added_at          timestamptz NOT NULL,
  deleted_at        timestamptz,
  hlc               app.hlc,
  PRIMARY KEY (deck_id, item_key),
  CHECK ((entry_seq IS NULL) <> (note_id IS NULL)),
  CHECK (item_key = CASE WHEN entry_seq IS NOT NULL THEN 'e:' || entry_seq::text ELSE 'n:' || note_id::text END)
);
CREATE INDEX deck_item_order_idx ON app.deck_item (deck_id, position, item_key) WHERE deleted_at IS NULL;
CREATE INDEX deck_item_entry_idx ON app.deck_item (entry_seq) WHERE entry_seq IS NOT NULL;
CREATE INDEX deck_item_note_idx  ON app.deck_item (note_id)   WHERE note_id IS NOT NULL;
COMMENT ON TABLE  app.deck_item IS 'Membership of an entry or a note in a deck, with new-card order and coverage count. Smart decks have no items.';
COMMENT ON COLUMN app.deck_item.item_key IS 'Natural identity inside the deck: "e:<entry_seq>" or "n:<note uuid, lowercase>". Two devices adding the same thing offline therefore converge on one row.';
COMMENT ON COLUMN app.deck_item.entry_seq IS 'Soft reference to ref.dict_entry.seq. Exactly one of entry_seq / note_id is set.';
COMMENT ON COLUMN app.deck_item.note_id IS 'For notes without a dictionary entry (phrases, sentences, custom, grammar, kanji).';
COMMENT ON COLUMN app.deck_item.position IS 'Ascending new-card order within the deck; ties broken by item_key. Sparse (clients space by 1024). Media decks: rank by in-deck frequency (1 = most frequent).';
COMMENT ON COLUMN app.deck_item.occurrence_count IS 'Occurrences of the entry in the deck''s media (sum over segments); 0 for non-media decks.';
COMMENT ON COLUMN app.deck_item.deleted_at IS 'Tombstone for removal from a user deck. Unlike other tombstones this one is reversible: the whole row is one LWW register (a deck.item_put with a newer hlc clears it).';
COMMENT ON COLUMN app.deck_item.hlc IS 'HLC of the last winning deck.item_put / deck.item_removed op (whole-row LWW). NULL for snapshot-delivered rows of media/list decks, which ops never touch.';

CREATE TABLE app.confusable (
  note_a_id   uuid        NOT NULL REFERENCES app.note (id),
  note_b_id   uuid        NOT NULL REFERENCES app.note (id),
  reason      text        NOT NULL CHECK (reason IN ('homophone', 'look_alike', 'meaning')),
  status      text        NOT NULL DEFAULT 'suggested' CHECK (status IN ('suggested', 'confirmed', 'rejected')),
  hlc         app.hlc     NOT NULL,
  created_at  timestamptz NOT NULL,
  updated_at  timestamptz NOT NULL,
  PRIMARY KEY (note_a_id, note_b_id, reason),
  CHECK (note_a_id < note_b_id)
);
CREATE INDEX confusable_b_idx ON app.confusable (note_b_id);
COMMENT ON TABLE  app.confusable IS 'An unordered pair of notes that get mixed up. Suggested by the server, confirmed or rejected by the user.';
COMMENT ON COLUMN app.confusable.note_a_id IS 'The smaller of the two note ids (uuid byte order = lowercase text order), so each pair has one row per reason.';
COMMENT ON COLUMN app.confusable.status IS 'One LWW register with hlc. suggested (server) -> confirmed|rejected (user). A user decision always beats a suggestion regardless of clock; between user decisions the higher hlc wins. Rejected rows stay so the pair is not suggested again.';

-- =============================================================================
-- app.* : media (server-built content; metadata via ops, bulk via snapshots)
-- =============================================================================

CREATE TABLE app.media (
  id                 uuid        PRIMARY KEY,
  title              text        NOT NULL CHECK (title <> ''),
  kind               text        NOT NULL CHECK (kind IN ('anime', 'novel', 'vn', 'manga', 'web', 'other')),
  language           text        NOT NULL DEFAULT 'ja',
  source             text        NOT NULL CHECK (source IN ('jpdb', 'file', 'url', 'paste')),
  jpdb_id            text,
  cover_blob_hash    text        CHECK (cover_blob_hash ~ '^[0-9a-f]{64}$'),
  parse_status       text        NOT NULL DEFAULT 'pending' CHECK (parse_status IN ('pending', 'parsing', 'parsed', 'failed')),
  parse_error        text,
  content_version    integer     NOT NULL DEFAULT 0 CHECK (content_version >= 0),
  content_blob_hash  text        CHECK (content_blob_hash ~ '^[0-9a-f]{64}$'),
  created_at         timestamptz NOT NULL,
  updated_at         timestamptz NOT NULL,
  deleted_at         timestamptz,
  clocks             jsonb       NOT NULL DEFAULT '{}'::jsonb CHECK (jsonb_typeof(clocks) = 'object')
);
CREATE UNIQUE INDEX media_live_jpdb_uq ON app.media (jpdb_id) WHERE jpdb_id IS NOT NULL AND deleted_at IS NULL;
CREATE INDEX media_title_trgm_idx ON app.media USING gin (title public.gin_trgm_ops);
COMMENT ON TABLE  app.media IS 'One imported work (a show, a book, ...). The row itself is small and travels through ops; its segments, sentences and occurrences are server-built and travel as a snapshot.';
COMMENT ON COLUMN app.media.source IS 'jpdb = pre-parsed jpdb deck (no sentences), file/url/paste = parsed by the worker. Immutable.';
COMMENT ON COLUMN app.media.jpdb_id IS 'jpdb deck id when source = jpdb; re-importing the same id updates this media instead of creating another.';
COMMENT ON COLUMN app.media.parse_status IS 'Server-owned (not a user register): pending -> parsing -> parsed|failed; parsed -> parsing on re-parse. Published to clients by media.content_published.';
COMMENT ON COLUMN app.media.content_version IS 'Bumped each time a (re-)parse publishes new segments/sentences/occurrences. 0 = nothing published yet.';
COMMENT ON COLUMN app.media.content_blob_hash IS 'Snapshot archive for content_version (segments, sentences, occurrences); NULL when content_version = 0.';
COMMENT ON COLUMN app.media.deleted_at IS 'Tombstone (permanent). After it is set the server hard-deletes the media''s segments, sentences, occurrences and DETECTED grammar spans (manual spans stay), and tombstones its deck.';
COMMENT ON COLUMN app.media.clocks IS 'LWW registers: title, kind, cover_blob_hash, deleted.';

CREATE TABLE app.media_segment (
  id                    uuid     PRIMARY KEY,
  media_id              uuid     NOT NULL REFERENCES app.media (id) ON DELETE CASCADE,
  ordinal               integer  NOT NULL CHECK (ordinal >= 0),
  kind                  text     NOT NULL CHECK (kind IN ('episode', 'chapter', 'volume', 'page', 'whole')),
  title                 text     NOT NULL DEFAULT '',
  sentence_count        integer  NOT NULL DEFAULT 0 CHECK (sentence_count >= 0),
  token_count           integer  NOT NULL DEFAULT 0 CHECK (token_count >= 0),
  unmapped_token_count  integer  NOT NULL DEFAULT 0 CHECK (unmapped_token_count >= 0),
  UNIQUE (media_id, ordinal),
  CHECK (unmapped_token_count <= token_count)
);
COMMENT ON TABLE  app.media_segment IS 'An episode, chapter or volume of a media, in order. Every media has at least one segment once parsed: jpdb imports and unsegmented text get a single segment of kind whole, ordinal 0.';
COMMENT ON COLUMN app.media_segment.id IS 'Generated by the worker on first parse and preserved across re-parses for the same (media_id, ordinal).';
COMMENT ON COLUMN app.media_segment.ordinal IS '0-based order within the media.';
COMMENT ON COLUMN app.media_segment.token_count IS 'All word tokens in the segment (punctuation and whitespace excluded): the denominator for raw-token coverage. Equals sum(occurrence.count) + unmapped_token_count.';
COMMENT ON COLUMN app.media_segment.unmapped_token_count IS 'Word tokens that matched no dictionary entry (names, unknown words).';

CREATE TABLE app.sentence (
  id               uuid     PRIMARY KEY,
  media_id         uuid     NOT NULL REFERENCES app.media (id) ON DELETE CASCADE,
  segment_id       uuid     NOT NULL REFERENCES app.media_segment (id) ON DELETE CASCADE,
  ordinal          integer  NOT NULL CHECK (ordinal >= 0),
  text             text     NOT NULL CHECK (text <> ''),
  tokens           jsonb    NOT NULL DEFAULT '[]'::jsonb CHECK (jsonb_typeof(tokens) = 'array'),
  origin           text     NOT NULL DEFAULT 'media' CHECK (origin IN ('media', 'generated')),
  start_ms         integer  CHECK (start_ms >= 0),
  end_ms           integer,
  audio_blob_hash  text     CHECK (audio_blob_hash ~ '^[0-9a-f]{64}$'),
  image_blob_hash  text     CHECK (image_blob_hash ~ '^[0-9a-f]{64}$'),
  location         jsonb,
  unknown_count    integer  CHECK (unknown_count >= 0),
  UNIQUE (segment_id, ordinal),
  CHECK ((start_ms IS NULL) = (end_ms IS NULL)),
  CHECK (end_ms IS NULL OR end_ms >= start_ms)
);
CREATE INDEX sentence_media_idx     ON app.sentence (media_id);
CREATE INDEX sentence_text_trgm_idx ON app.sentence USING gin (text public.gin_trgm_ops);
COMMENT ON TABLE  app.sentence IS 'One sentence (or subtitle line) of a media segment, with its tokenisation.';
COMMENT ON COLUMN app.sentence.id IS 'Generated by the worker. A re-parse MUST keep the id of every sentence whose (segment_id, ordinal, text) is unchanged, because notes, review_log and manual grammar spans point at it (all soft references).';
COMMENT ON COLUMN app.sentence.media_id IS 'Denormalised from the segment; always equals media_segment.media_id.';
COMMENT ON COLUMN app.sentence.text IS 'Original text (not normalised).';
COMMENT ON COLUMN app.sentence.tokens IS 'Parser output: [{"s":0,"e":2,"surface":"食べ","lemma":"食べる","reading":"たべ","pos":["動詞","一般"],"cform":"連用形","seq":1358280,"class":"content","override":false}]. s/e are UTF-16 code-unit offsets into text, half-open, ascending, non-overlapping; gaps are untokenised text (punctuation). seq null = unmapped. class as occurrence.pos_class. Shape is finalised by the parser contract.';
COMMENT ON COLUMN app.sentence.origin IS 'media = from the imported source; generated = LLM-generated example (always shown labelled, never counted in coverage).';
COMMENT ON COLUMN app.sentence.start_ms IS 'Subtitle start within the segment''s video/audio; NULL for text sources.';
COMMENT ON COLUMN app.sentence.location IS 'Source position for non-timed media, e.g. manga {"page":12,"box":[x,y,w,h]} or EPUB {"cfi":"..."}; NULL if none.';
COMMENT ON COLUMN app.sentence.unknown_count IS 'Reserved cache for i+1 queries (number of distinct not-known entries); NULL = not computed. Server-only; not part of snapshots.';

CREATE TABLE app.sentence_grammar_span (
  sentence_id       uuid        NOT NULL,
  grammar_point_id  uuid        NOT NULL REFERENCES app.grammar_point (id),
  start_offset      integer     NOT NULL CHECK (start_offset >= 0),
  end_offset        integer     NOT NULL,
  origin            text        NOT NULL CHECK (origin IN ('detected', 'manual')),
  media_id          uuid,
  rule_index        smallint    CHECK (rule_index >= 0),
  created_at        timestamptz NOT NULL DEFAULT now(),
  deleted_at        timestamptz,
  hlc               app.hlc,
  PRIMARY KEY (sentence_id, grammar_point_id, start_offset, end_offset, origin),
  CHECK (end_offset > start_offset),
  CHECK ((origin = 'manual') = (hlc IS NOT NULL)),
  CHECK (origin = 'manual' OR deleted_at IS NULL),
  CHECK (origin = 'manual' OR media_id IS NOT NULL)
);
CREATE INDEX sentence_grammar_span_point_idx ON app.sentence_grammar_span (grammar_point_id) WHERE deleted_at IS NULL;
CREATE INDEX sentence_grammar_span_media_idx ON app.sentence_grammar_span (media_id) WHERE origin = 'detected';
COMMENT ON TABLE  app.sentence_grammar_span IS 'Where a grammar point occurs in a sentence ("tagged spans on sentence"). The primary key is the natural identity, so two devices highlighting the same span converge on one row. detected rows are media content: the worker replaces them on every (re-)parse and rule change. manual rows are op-synced user data ("I saw something weird"): never hard-deleted, not even when the sentence or media disappears.';
COMMENT ON COLUMN app.sentence_grammar_span.sentence_id IS 'Soft reference to app.sentence.id (no foreign key on either side): a manual span may outlive its sentence, and an offline grammar.span_put for a sentence the server has since purged is still accepted. Readers hide spans whose sentence is missing.';
COMMENT ON COLUMN app.sentence_grammar_span.start_offset IS 'UTF-16 code-unit offset into sentence.text, inclusive; end_offset exclusive.';
COMMENT ON COLUMN app.sentence_grammar_span.origin IS 'detected | manual. Part of the key: a manual and a detected row may cover the same span.';
COMMENT ON COLUMN app.sentence_grammar_span.media_id IS 'detected: the sentence''s media, so the worker can delete by media (DELETE ... WHERE media_id = $1 AND origin = ''detected''). manual: optional hint, may be NULL.';
COMMENT ON COLUMN app.sentence_grammar_span.rule_index IS 'detected: index into grammar_point.detection_rules that matched. NULL for manual.';
COMMENT ON COLUMN app.sentence_grammar_span.deleted_at IS 'manual only: reversible tombstone, like deck_item (the whole row is one LWW register; grammar.span_put with a newer hlc clears it). Detected rows are hard-deleted on rebuild.';
COMMENT ON COLUMN app.sentence_grammar_span.hlc IS 'manual only: HLC of the last winning grammar.span_put / grammar.span_removed op.';

CREATE TABLE app.occurrence (
  segment_id    uuid    NOT NULL REFERENCES app.media_segment (id) ON DELETE CASCADE,
  entry_seq     bigint  NOT NULL CHECK (entry_seq > 0),
  media_id      uuid    NOT NULL REFERENCES app.media (id) ON DELETE CASCADE,
  count         integer NOT NULL CHECK (count > 0),
  pos_class     text    NOT NULL DEFAULT 'content' CHECK (pos_class IN ('content', 'particle', 'auxiliary', 'name', 'other')),
  sentence_ids  uuid[]  NOT NULL DEFAULT '{}' CHECK (cardinality(sentence_ids) <= 20),
  PRIMARY KEY (segment_id, entry_seq)
);
CREATE INDEX occurrence_entry_idx ON app.occurrence (entry_seq, media_id);
CREATE INDEX occurrence_media_idx ON app.occurrence (media_id, entry_seq);
COMMENT ON TABLE  app.occurrence IS 'How often a dictionary entry occurs in a media segment. Per-media numbers are sums over segments.';
COMMENT ON COLUMN app.occurrence.entry_seq IS 'Soft reference to ref.dict_entry.seq.';
COMMENT ON COLUMN app.occurrence.media_id IS 'Denormalised from the segment.';
COMMENT ON COLUMN app.occurrence.count IS 'Number of tokens in the segment mapped to this entry.';
COMMENT ON COLUMN app.occurrence.pos_class IS 'Coverage filter class of the entry''s most frequent use in this segment: content, particle, auxiliary, name, other.';
COMMENT ON COLUMN app.occurrence.sentence_ids IS 'Up to 20 sentences of this segment containing the entry, in ordinal order ("sentence references"); {} for jpdb imports. Soft references.';

CREATE TABLE app.parse_override (
  id           uuid        PRIMARY KEY,
  media_id     uuid,
  sentence_id  uuid,
  match_text   text        NOT NULL CHECK (match_text <> ''),
  tokens       jsonb       NOT NULL CHECK (jsonb_typeof(tokens) = 'array' AND jsonb_array_length(tokens) > 0),
  note         text        NOT NULL DEFAULT '',
  created_at   timestamptz NOT NULL,
  updated_at   timestamptz NOT NULL,
  deleted_at   timestamptz,
  hlc          app.hlc     NOT NULL,
  CHECK (sentence_id IS NULL OR media_id IS NOT NULL)
);
CREATE INDEX parse_override_match_idx ON app.parse_override (match_text) WHERE deleted_at IS NULL;
CREATE INDEX parse_override_media_idx ON app.parse_override (media_id) WHERE deleted_at IS NULL;
COMMENT ON TABLE  app.parse_override IS 'A user correction to tokenisation, re-applied by every parse. Server only (the phone does not parse) but still mutated through ops.';
COMMENT ON COLUMN app.parse_override.media_id IS 'Scope. NULL = applies to all media; set = only that media. Soft reference.';
COMMENT ON COLUMN app.parse_override.sentence_id IS 'Narrowest scope: only this sentence (requires media_id). Soft reference. Most specific scope wins: sentence > media > global; within a scope the longest match_text, then the highest hlc.';
COMMENT ON COLUMN app.parse_override.match_text IS 'Exact surface substring of the sentence text that this override re-tokenises.';
COMMENT ON COLUMN app.parse_override.tokens IS 'Replacement tokens whose surfaces concatenate to match_text: [{"surface":"食べ","lemma":"食べる","seq":1358280}]; seq null = force "no entry".';
COMMENT ON COLUMN app.parse_override.hlc IS 'Whole-row LWW clock (parse_override.put / parse_override.deleted). Delete is permanent.';
